insert into public.store_settings (
  id, business_name, tagline, phone, whatsapp, email, address, county, business_hours, about, payment_instructions,
  deposit_percent, delivery_mode, fixed_delivery_fee, default_delivery_fee, free_delivery_threshold,
  facebook_url, instagram_url
) values (
  1, 'BeiHub', 'Quality Products. Better Prices. Delivered.', '+254 700 000 000', '254700000000', 'hello@beihub.co.ke', 'Update your shop address in Admin > Settings', 'Nairobi',
  'Mon - Sat: 8:00am - 6:00pm', 'BeiHub is a Kenyan catalogue and order desk for electronics, appliances, water tanks and solar equipment. Browse prices, pick what you need and send your order list. We confirm every order personally.', 'After you submit your order we will call or WhatsApp you to confirm availability and delivery, and send our M-Pesa / bank details for the 50% deposit. The balance is paid when your order is delivered.', 50, 'county', 1500, 2500,
  null::numeric, null, null
) on conflict (id) do nothing;

