insert into public.products (category_id, name, slug, brand, short_description, description, specs, is_featured, is_popular, is_new)
select c.id, v.name, v.slug, v.brand, v.short_description, v.description, v.specs, v.is_featured, v.is_popular, v.is_new
from (values
  ('water-tanks'::text, 'Water Tank'::text, 'water-tank'::text, null::text, 'Vertical food-grade polyethylene water tank with UV protection.'::text, 'A durable vertical water tank moulded from food-grade polyethylene with UV stabilisers, so water stays clean and the tank stands up to the Kenyan sun. Suitable for homes, farms, schools and commercial sites. Every tank has a screw lid and a 1-inch outlet boss for fittings.'::text, '{"Material":"Food-grade polyethylene (LLDPE)","UV protection":"Yes","Outlet":"1 inch","Lid":"Screw-on, lockable","Warranty":"5 years on the tank body"}'::jsonb, true, true, false),
  ('water-tanks'::text, 'Triple-Layer Water Tank'::text, 'triple-layer-water-tank'::text, null::text, 'Three-layer tank that blocks light to keep water fresher for longer.'::text, 'The black inner layer blocks sunlight to reduce algae growth, the middle layer adds strength and the outer layer resists UV. A good choice for drinking-water storage and for sites with strong sun.'::text, '{"Material":"Three-layer polyethylene","Light blocking":"Black inner layer","UV protection":"Yes","Outlet":"1 inch"}'::jsonb, false, false, true),
  ('water-tanks'::text, 'Tank Fittings Kit'::text, 'tank-fittings-kit'::text, null::text, 'Ball valve, float valve, unions and sockets to plumb your tank.'::text, 'Everything needed to connect a water tank: brass ball valve, float valve, tank connector, socket and elbow. Choose the pipe size that matches your plumbing.'::text, '{"Contents":"Ball valve, float valve, tank connector, socket, elbow","Material":"Brass and PVC"}'::jsonb, false, false, false),
  ('tvs-entertainment'::text, 'Samsung 4K UHD Smart TV'::text, 'samsung-4k-uhd-smart-tv'::text, 'Samsung'::text, '4K Ultra HD smart television with built-in streaming apps.'::text, 'Crisp 4K picture, built-in Wi-Fi and popular streaming apps ready to use. Includes remote control and wall-mount compatible back panel. Choose the screen size that suits your room.'::text, '{"Resolution":"3840 x 2160 (4K UHD)","Smart TV":"Yes, with streaming apps","Connectivity":"Wi-Fi, Bluetooth, 3 x HDMI, 1 x USB","Warranty":"1 year"}'::jsonb, true, true, false),
  ('tvs-entertainment'::text, 'LG UHD Smart TV'::text, 'lg-uhd-smart-tv'::text, 'LG'::text, 'UHD smart TV with webOS and voice-ready remote.'::text, 'UHD resolution, a fast processor and an easy-to-use smart interface. Slim bezel design for a clean look on a stand or on the wall.'::text, '{"Resolution":"3840 x 2160 (UHD)","Smart TV":"Yes","Connectivity":"Wi-Fi, Bluetooth, 3 x HDMI, 2 x USB","Warranty":"1 year"}'::jsonb, false, false, true),
  ('tvs-entertainment'::text, 'Hisense Full HD Smart TV'::text, 'hisense-full-hd-smart-tv'::text, 'Hisense'::text, 'Affordable Full HD smart TV for the bedroom or living room.'::text, 'A budget-friendly smart TV with Full HD picture, built-in Wi-Fi and streaming apps.'::text, '{"Resolution":"1920 x 1080 (Full HD)","Smart TV":"Yes","Connectivity":"Wi-Fi, 2 x HDMI, 1 x USB","Warranty":"1 year"}'::jsonb, false, true, false),
  ('speakers-sound'::text, 'Portable Bluetooth Speaker'::text, 'portable-bluetooth-speaker'::text, 'JBL'::text, 'Rechargeable wireless speaker with deep bass.'::text, 'Pair with your phone over Bluetooth and enjoy loud, clear sound at home, in the shop or outdoors. Rechargeable battery, USB charging and a carry strap.'::text, '{"Connectivity":"Bluetooth 5.0, AUX, USB","Battery":"Rechargeable lithium","Water resistance":"Splash resistant"}'::jsonb, false, true, false),
  ('speakers-sound'::text, 'Soundbar with Subwoofer'::text, 'soundbar-with-subwoofer'::text, 'LG'::text, 'Wireless subwoofer and soundbar to upgrade your TV sound.'::text, 'Connects to your TV by HDMI ARC, optical or Bluetooth. A wireless subwoofer adds punchy bass for movies, football and music.'::text, '{"Connectivity":"HDMI ARC, Optical, Bluetooth, USB","Subwoofer":"Wireless","Remote":"Included"}'::jsonb, false, true, false),
  ('speakers-sound'::text, 'Home Theatre System'::text, 'home-theatre-system'::text, 'Sony'::text, 'Surround sound system with tower speakers and AV receiver.'::text, 'Fill your living room with powerful surround sound. Includes tower speakers, centre speaker, subwoofer and receiver with HDMI and Bluetooth.'::text, '{"Connectivity":"HDMI, Optical, Bluetooth, USB","Includes":"Receiver, tower speakers, centre speaker, subwoofer"}'::jsonb, false, false, true),
  ('refrigerators-freezers'::text, 'Single Door Refrigerator'::text, 'single-door-refrigerator'::text, 'Ramtons'::text, 'Compact single door fridge with a small freezer compartment.'::text, 'A practical choice for bedsitters, offices and small families. Adjustable shelves, vegetable crisper and a built-in freezer compartment.'::text, '{"Type":"Direct cool, single door","Energy use":"Low consumption","Warranty":"1 year"}'::jsonb, false, true, false),
  ('refrigerators-freezers'::text, 'Double Door Refrigerator'::text, 'double-door-refrigerator'::text, 'Hisense'::text, 'Top-freezer double door fridge with a spacious fresh-food section.'::text, 'Frost-free cooling, separate freezer and fridge doors and a steel-look finish. Plenty of space for a family.'::text, '{"Type":"Frost free, top freezer","Finish":"Stainless-steel look","Warranty":"2 years"}'::jsonb, true, true, false),
  ('refrigerators-freezers'::text, 'Side-by-Side Refrigerator'::text, 'side-by-side-refrigerator'::text, 'LG'::text, 'Large side-by-side fridge-freezer with water dispenser.'::text, 'A large-capacity fridge-freezer with external water dispenser and digital temperature control. Built for big households and hospitality.'::text, '{"Type":"Frost free, side-by-side","Dispenser":"Water","Warranty":"2 years"}'::jsonb, false, false, true),
  ('refrigerators-freezers'::text, 'Chest Freezer'::text, 'chest-freezer'::text, 'Von'::text, 'Deep chest freezer for bulk storage of meat, fish and drinks.'::text, 'Strong cooling for shops, butcheries and homes. Lockable lid, removable basket and fast-freeze switch. Great value for bulk storage.'::text, '{"Type":"Chest, manual defrost","Lid":"Lockable","Warranty":"1 year"}'::jsonb, false, true, false),
  ('home-appliances'::text, 'Microwave Oven'::text, 'microwave-oven'::text, 'Ramtons'::text, 'Digital microwave with multiple power levels and defrost.'::text, 'Heat, cook and defrost quickly. Digital controls, multiple power levels and a easy-clean interior.'::text, '{"Control":"Digital","Functions":"Reheat, cook, defrost","Warranty":"1 year"}'::jsonb, false, false, false),
  ('home-appliances'::text, 'Front-Load Washing Machine'::text, 'front-load-washing-machine'::text, 'Hisense'::text, 'Energy-efficient front loader with multiple wash programmes.'::text, 'Inverter motor, quick wash and several programmes for different fabrics. Choose the drum capacity for your household.'::text, '{"Type":"Front load, fully automatic","Motor":"Inverter","Warranty":"2 years"}'::jsonb, false, false, false),
  ('computers-laptops'::text, 'Business Laptop 15.6 Inch'::text, 'business-laptop-15'::text, 'HP'::text, 'Reliable 15.6 inch laptop for work, school and business.'::text, 'Full HD display, fast SSD storage, backlit-ready keyboard and long battery life. Windows 11 ready. Choose the processor, memory and storage that fit your budget.'::text, '{"Display":"15.6 inch Full HD","Operating system":"Windows 11","Warranty":"1 year"}'::jsonb, true, true, false),
  ('computers-laptops'::text, 'Desktop Computer Set'::text, 'desktop-computer-set'::text, 'Dell'::text, 'Tower, monitor, keyboard and mouse - ready to plug in.'::text, 'A complete desktop set for the office, cyber or home. Includes tower, LED monitor, keyboard and mouse.'::text, '{"Includes":"Tower, monitor, keyboard, mouse","Operating system":"Windows 11","Warranty":"1 year"}'::jsonb, false, false, false),
  ('computers-laptops'::text, 'LED Monitor'::text, 'led-monitor'::text, 'Lenovo'::text, 'Slim-bezel LED monitor with HDMI input.'::text, 'A sharp, flicker-free display for work, CCTV viewing and entertainment. HDMI and VGA inputs, wall-mountable.'::text, '{"Panel":"IPS LED","Inputs":"HDMI, VGA","Refresh rate":"75Hz","Warranty":"1 year"}'::jsonb, false, false, false),
  ('cctv-security'::text, 'Outdoor CCTV Bullet Camera'::text, 'outdoor-cctv-bullet-camera'::text, 'Hikvision'::text, 'Weatherproof bullet camera with night vision.'::text, 'Metal housing, IP66 weather protection and infrared night vision up to 30 metres. Works with DVR/NVR recorders.'::text, '{"Weather rating":"IP66","Night vision":"Up to 30m","Housing":"Metal"}'::jsonb, false, true, false),
  ('cctv-security'::text, 'CCTV Camera Kit'::text, 'cctv-camera-kit'::text, 'Hikvision'::text, 'Complete kit: cameras, recorder, hard drive, cables and power supply.'::text, 'A complete security kit ready for installation. Includes cameras, DVR, hard drive, power supply and connectors. Installation can be arranged on request.'::text, '{"Includes":"Cameras, DVR, 1TB HDD, cables, power supply","Remote viewing":"Phone app"}'::jsonb, true, true, false),
  ('cctv-security'::text, 'DVR / NVR Recorder'::text, 'dvr-nvr-recorder'::text, 'Hikvision'::text, 'Digital video recorders for analogue and IP cameras.'::text, 'Record and play back CCTV footage with phone app viewing. Supports hard drives up to 8TB (hard drive sold separately).'::text, '{"Remote viewing":"Phone app","Hard drive":"Not included"}'::jsonb, false, false, false),
  ('networking-wifi'::text, 'Wi-Fi Router'::text, 'wifi-router'::text, 'TP-Link'::text, 'Dual-band Wi-Fi routers for home and office.'::text, 'Fast, stable Wi-Fi for streaming and video calls. Easy setup with a phone app. The 4G LTE model takes a SIM card so you can get internet without a fixed line.'::text, '{"Setup":"Phone app","Ports":"Gigabit LAN","Warranty":"1 year"}'::jsonb, false, true, true),
  ('networking-wifi'::text, 'Gigabit Network Switch'::text, 'network-switch'::text, 'TP-Link'::text, 'Plug-and-play gigabit switches for offices and CCTV.'::text, 'Expand your wired network with gigabit ports. No configuration needed. Metal case suitable for desk or rack mounting.'::text, '{"Speed":"10/100/1000 Mbps","Management":"Unmanaged","Warranty":"1 year"}'::jsonb, false, false, false),
  ('networking-wifi'::text, 'Wireless Access Point'::text, 'wireless-access-point'::text, 'Tenda'::text, 'Ceiling-mount and outdoor access points for wide Wi-Fi coverage.'::text, 'Extend Wi-Fi coverage in offices, hotels and schools. Powered over Ethernet (PoE) for a clean installation.'::text, '{"Power":"PoE","Coverage":"Wide-area"}'::jsonb, false, false, false),
  ('solar-equipment'::text, 'Monocrystalline Solar Panel'::text, 'monocrystalline-solar-panel'::text, null::text, 'High-efficiency solar panels for homes, farms and businesses.'::text, 'Monocrystalline cells for strong output even in low light. Aluminium frame and tempered glass built for Kenyan weather. Choose the wattage that matches your system design.'::text, '{"Cell type":"Monocrystalline","Frame":"Anodised aluminium","Performance warranty":"25 years","Product warranty":"10 years"}'::jsonb, true, true, false),
  ('solar-equipment'::text, 'Solar Charge Controller'::text, 'solar-charge-controller'::text, null::text, 'Protects your battery and improves charging efficiency.'::text, 'LCD charge controller with overload, short-circuit and over-charge protection. MPPT models harvest more power from your panels.'::text, '{"Display":"LCD","Protection":"Overload, short circuit, over-charge"}'::jsonb, false, false, false),
  ('solar-equipment'::text, 'Solar Cable & MC4 Connector Kit'::text, 'solar-cable-mc4-kit'::text, null::text, 'UV-resistant solar cable with MC4 connectors.'::text, 'Twin-core solar cable with a pair of MC4 connectors fitted. Sunlight and weather resistant.'::text, '{"Cable":"4mm2 solar cable","Connectors":"MC4 pair"}'::jsonb, false, false, false),
  ('inverters-batteries'::text, 'Deep Cycle Solar Battery'::text, 'deep-cycle-solar-battery'::text, null::text, '12V deep-cycle batteries for solar, inverter and UPS systems.'::text, 'Maintenance-free deep cycle battery made for daily charge and discharge. Pair with a solar charge controller and inverter.'::text, '{"Voltage":"12V","Type":"Deep cycle, maintenance free","Warranty":"1 year"}'::jsonb, true, true, false),
  ('inverters-batteries'::text, 'Hybrid Solar Inverter'::text, 'hybrid-solar-inverter'::text, null::text, 'Pure sine wave hybrid inverter with built-in solar charger.'::text, 'Runs household appliances from batteries and solar, and switches to grid power when needed. Pure sine wave output with an LCD status display.'::text, '{"Output":"Pure sine wave","Display":"LCD","Input":"Solar + grid","Warranty":"2 years"}'::jsonb, true, false, true),
  ('water-pumps'::text, 'Surface Water Pump'::text, 'surface-water-pump'::text, null::text, 'Electric surface pumps for tanks, gardens and small farms.'::text, 'Copper-wound motor with a cast-iron pump head for steady water delivery. Ideal for filling tanks and irrigation.'::text, '{"Motor":"Copper winding","Pump head":"Cast iron","Power":"Single phase 240V"}'::jsonb, false, true, false),
  ('water-pumps'::text, 'Pressure Booster Pump'::text, 'pressure-booster-pump'::text, null::text, 'Automatic booster pump with pressure vessel and gauge.'::text, 'Boost low water pressure throughout the house. Automatic start and stop with pressure switch and gauge.'::text, '{"Control":"Automatic pressure switch","Gauge":"Included","Power":"Single phase 240V"}'::jsonb, false, false, true),
  ('water-pumps'::text, 'Borehole Submersible Pump'::text, 'borehole-submersible-pump'::text, null::text, 'Stainless-steel submersible pumps for boreholes and wells.'::text, 'Stainless-steel body for long life underwater. Supplied with a cable. Choose the power for your depth and flow requirements.'::text, '{"Body":"Stainless steel","Use":"Boreholes and deep wells"}'::jsonb, false, false, false),
  ('power-equipment'::text, 'Petrol Generator'::text, 'petrol-generator'::text, null::text, 'Portable petrol generators with recoil start.'::text, 'Reliable backup power for homes, shops and sites. Air-cooled engine, AVR for stable output and wheels for easy moving.'::text, '{"Fuel":"Petrol","Start":"Recoil (key start on larger sizes)","Output":"230V AC"}'::jsonb, false, true, false),
  ('power-equipment'::text, 'Automatic Voltage Regulator'::text, 'automatic-voltage-regulator'::text, null::text, 'Protect TVs, fridges and computers from voltage spikes.'::text, 'Stabilises mains voltage and protects your appliances. Digital voltage display and time-delay protection.'::text, '{"Display":"Digital voltage","Protection":"Over and under voltage"}'::jsonb, false, false, false),
  ('electronics'::text, 'Power Bank'::text, 'power-bank'::text, null::text, 'Fast-charging power banks with dual USB output.'::text, 'Keep phones, earbuds and tablets charged on the go. LED charge indicator and dual USB output.'::text, '{"Output":"Dual USB","Indicator":"LED"}'::jsonb, false, false, false),
  ('electronics'::text, 'Wireless Earbuds'::text, 'wireless-earbuds'::text, null::text, 'Bluetooth earbuds with charging case.'::text, 'True wireless earbuds with clear sound, touch controls and a pocket charging case.'::text, '{"Connectivity":"Bluetooth 5.3","Case battery":"Up to 20 hours total"}'::jsonb, false, false, true),
  ('other-accessories'::text, 'Surge-Protected Extension Socket'::text, 'surge-protected-extension-socket'::text, null::text, 'Extension sockets with surge protection and switch.'::text, 'Safe multi-way extension with surge protection, individual overload protection and a 3-metre cable.'::text, '{"Cable":"3 metres","Protection":"Surge and overload"}'::jsonb, false, false, false),
  ('other-accessories'::text, 'TV Wall Mount Bracket'::text, 'tv-wall-mount-bracket'::text, null::text, 'Tilting TV wall brackets for flat-screen TVs.'::text, 'Strong steel bracket with tilt adjustment. Screws and fixings included.'::text, '{"Material":"Steel","Includes":"Screws and fixings"}'::jsonb, false, false, false)
) as v(category_slug, name, slug, brand, short_description, description, specs, is_featured, is_popular, is_new)
join public.categories c on c.slug = v.category_slug
on conflict (slug) do nothing;

